import React, { useState, useEffect } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  primaryLight: '#EEF2FF',
  success: '#10B981',
  successLight: '#DCFCE7',
  danger: '#EF4444',
  dangerLight: '#FEE2E2',
  warning: '#F59E0B',
  warningLight: '#FEF3C7',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const Dashboard = () => {
  // ============ STATE ============
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: null
  });
  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);

  // ============ LOAD DATA ============
  const loadData = async () => {
    try {
      console.log('📊 [DASHBOARD] Loading data...');
      setLoading(true);
      setError(null);

      // Exécution parallèle pour la performance
      const [studentStatsRes, attendanceStatsRes, logRes, statusRes] = await Promise.all([
        studentsAPI.getStats(),      // /students/stats/
        attendanceAPI.getStats(),    // /attendance/stats/
        attendanceAPI.getTodayLog(), // /attendance/
        attendanceAPI.getStatus()     // /attendance/status/
      ]);

      console.log('📥 [DASHBOARD] Raw responses received');

      // 1. Traitement des stats globales
      const sData = studentStatsRes.data || {};
      const aSummary = attendanceStatsRes.data || {};

      const active = Number(sData.active_students) || 0;
      const present = Number(sData.total_attendance) || 0;

      setStats({
        active_students: active,
        present_today: present,
        absent_today: Math.max(0, active - present),
        summary: aSummary // Contient avg_confidence, etc.
      });

      // 2. Traitement du registre récent (extraction de .records)
      const logs = logRes.data?.records || logRes.data || [];
      setAttendanceLog(Array.isArray(logs) ? logs : []);

      // 3. Traitement du statut complet (extraction de .students)
      const students = statusRes.data?.students || statusRes.data || [];
      setStatusList(Array.isArray(students) ? students : []);

      setLastUpdated(new Date().toLocaleTimeString());
      console.log('✅ [DASHBOARD] Data synchronized successfully');

    } catch (err) {
      const errorMsg = err.response?.data?.error || err.message || 'Erreur de liaison backend';
      console.error('❌ [DASHBOARD] Error:', errorMsg);
      setError(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  // ============ INITIALIZATION ============
  useEffect(() => {
    console.log('🎬 [DASHBOARD] Component mounted');
    loadData();
    return () => console.log('🛑 [DASHBOARD] Component unmounted');
  }, []);

  // ============ RENDER HELPERS ============
  if (error) {
    return (
      <div style={styles.container}>
        <div style={styles.errorCard}>
          <div style={styles.errorIcon}>⚠️</div>
          <h3 style={styles.errorTitle}>Erreur de connexion</h3>
          <p style={styles.errorText}>{error}</p>
          <button onClick={loadData} style={styles.retryBtn}>🔄 Réessayer</button>
        </div>
      </div>
    );
  }

  if (loading && !lastUpdated) {
    return (
      <div style={styles.container}>
        <div style={styles.loadingCard}>
          <div style={styles.spinner}></div>
          <p>Chargement des données temps réel...</p>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      {/* Header avec refresh manuel */}
      <div style={styles.header}>
        <div>
          <h2 style={styles.title}>Vue d'ensemble</h2>
          {lastUpdated && (
            <p style={styles.subtitle}>Dernière synchronisation: {lastUpdated}</p>
          )}
        </div>
        <button onClick={loadData} style={styles.refreshBtn} disabled={loading}>
          {loading ? '⌛...' : '🔄 Rafraîchir'}
        </button>
      </div>

      {/* STAT CARDS */}
      <div style={styles.statsGrid}>
        <StatCard icon="👥" label="Inscrits" value={stats.active_students} color={COLORS.primary} bgColor={COLORS.primaryLight} />
        <StatCard icon="✅" label="Présents" value={stats.present_today} color={COLORS.success} bgColor={COLORS.successLight} />
        <StatCard icon="❌" label="Absents" value={stats.absent_today} color={COLORS.danger} bgColor={COLORS.dangerLight} />
        <StatCard 
          icon="📊" 
          label="Taux" 
          value={stats.active_students > 0 ? `${((stats.present_today / stats.active_students) * 100).toFixed(1)}%` : '0%'} 
          color={COLORS.warning} 
          bgColor={COLORS.warningLight}
        />
      </div>

      {/* MAIN CONTENT */}
      <div style={styles.mainGrid}>
        {/* REGISTRE RÉCENT (LOGS) */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>📋 Derniers Scans</h3>
          {attendanceLog.length === 0 ? (
            <div style={styles.emptyState}><p>Aucun scan aujourd'hui</p></div>
          ) : (
            <div style={styles.table}>
              <div style={styles.tableHeader}>
                <div style={{ flex: 2 }}>Étudiant</div>
                <div style={{ flex: 1 }}>Score IA</div>
                <div style={{ flex: 1 }}>Heure</div>
              </div>
              {attendanceLog.slice(0, 8).map((record, idx) => (
                <div key={idx} style={styles.tableRow}>
                  <div style={{ flex: 2, fontWeight: 600 }}>{record.student}</div>
                  <div style={{ flex: 1 }}><ConfidenceBadge confidence={record.confidence} /></div>
                  <div style={{ flex: 1, color: COLORS.textMuted }}>{record.timestamp}</div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* SUMMARY / STATS IA */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>📈 Analyse Data</h3>
          <div style={styles.summaryBox}>
            <SummaryItem label="Total Scans" value={stats.summary?.total_records || 0} color={COLORS.primary} />
            <SummaryItem label="Étudiants Identifiés" value={stats.summary?.unique_students || 0} color={COLORS.success} />
            <SummaryItem 
               label="Précision Moyenne" 
               value={stats.summary?.avg_confidence ? `${(stats.summary.avg_confidence * 100).toFixed(1)}%` : 'N/A'} 
               color={COLORS.warning} 
            />
          </div>
        </div>
      </div>

      {/* FULL STATUS LIST */}
      <div style={styles.section}>
        <h3 style={styles.sectionTitle}>👥 Liste de Présence Complète</h3>
        {statusList.length === 0 ? (
          <div style={styles.emptyState}><p>Aucun étudiant dans la base</p></div>
        ) : (
          <div style={styles.table}>
            <div style={styles.tableHeader}>
              <div style={{ flex: 2 }}>Nom</div>
              <div style={{ flex: 2 }}>Email</div>
              <div style={{ flex: 1 }}>Statut</div>
            </div>
            {statusList.map((student, idx) => (
              <div key={idx} style={styles.tableRow}>
                <div style={{ flex: 2, fontWeight: 500 }}>{student.name}</div>
                <div style={{ flex: 2, fontSize: '0.85rem', color: COLORS.textMuted }}>{student.email}</div>
                <div style={{ flex: 1 }}><StatusBadge present={student.present} /></div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

// ============ SUB-COMPONENTS ============

const StatCard = ({ icon, label, value, color, bgColor }) => (
  <div style={{ ...styles.statCard, borderLeft: `5px solid ${color}` }}>
    <div style={{ ...styles.statIconWrapper, backgroundColor: bgColor }}>{icon}</div>
    <div style={styles.statContent}>
      <p style={styles.statLabel}>{label}</p>
      <p style={{ ...styles.statValue, color }}>{value}</p>
    </div>
  </div>
);

const ConfidenceBadge = ({ confidence }) => {
  const score = confidence || 0;
  const isHigh = score >= 0.8;
  const isMid = score >= 0.6;

  const bg = isHigh ? COLORS.successLight : isMid ? COLORS.warningLight : COLORS.dangerLight;
  const tc = isHigh ? '#166534' : isMid ? '#92400E' : '#991B1B';

  return (
    <span style={{ padding: '4px 8px', backgroundColor: bg, color: tc, borderRadius: '4px', fontSize: '0.8rem', fontWeight: 700 }}>
      {(score * 100).toFixed(0)}%
    </span>
  );
};

const StatusBadge = ({ present }) => (
  <span style={{ 
    padding: '6px 12px', 
    backgroundColor: present ? COLORS.successLight : COLORS.dangerLight, 
    color: present ? '#166534' : '#991B1B', 
    borderRadius: '6px', fontSize: '0.85rem', fontWeight: 700 
  }}>
    {present ? 'PRÉSENT' : 'ABSENT'}
  </span>
);

const SummaryItem = ({ label, value, color }) => (
  <div style={styles.summaryItem}>
    <p style={styles.summaryLabel}>{label}</p>
    <p style={{ ...styles.summaryValue, color }}>{value}</p>
  </div>
);

// ============ STYLES ============
const styles = {
  container: { padding: '25px', maxWidth: '1400px', margin: '0 auto', fontFamily: 'Inter, system-ui, sans-serif' },
  header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' },
  title: { margin: 0, fontSize: '1.8rem', fontWeight: 800, color: COLORS.textMain },
  subtitle: { margin: '5px 0 0 0', fontSize: '0.85rem', color: COLORS.textMuted },
  refreshBtn: { padding: '10px 20px', backgroundColor: COLORS.primary, color: 'white', border: 'none', borderRadius: '8px', fontWeight: 600, cursor: 'pointer' },
  statsGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px', marginBottom: '30px' },
  statCard: { padding: '20px', backgroundColor: COLORS.surface, borderRadius: '12px', border: `1px solid ${COLORS.border}`, display: 'flex', alignItems: 'center', gap: '15px' },
  statIconWrapper: { width: '45px', height: '45px', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.5rem' },
  statLabel: { margin: 0, fontSize: '0.8rem', color: COLORS.textMuted, fontWeight: 600, textTransform: 'uppercase' },
  statValue: { margin: 0, fontSize: '1.8rem', fontWeight: 800 },
  mainGrid: { display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px', marginBottom: '30px' },
  section: { backgroundColor: COLORS.surface, borderRadius: '12px', border: `1px solid ${COLORS.border}`, padding: '20px', marginBottom: '20px' },
  sectionTitle: { margin: '0 0 20px 0', fontSize: '1.1rem', fontWeight: 700, color: COLORS.textMain },
  table: { width: '100%' },
  tableHeader: { display: 'flex', padding: '12px', backgroundColor: '#F8FAFC', borderRadius: '8px', fontWeight: 600, fontSize: '0.85rem', color: COLORS.textMuted, marginBottom: '10px' },
  tableRow: { display: 'flex', padding: '12px', borderBottom: `1px solid ${COLORS.background}`, alignItems: 'center', fontSize: '0.95rem' },
  emptyState: { padding: '40px', textAlign: 'center', color: COLORS.textMuted },
  summaryBox: { display: 'grid', gap: '15px' },
  summaryItem: { padding: '15px', backgroundColor: COLORS.background, borderRadius: '10px', border: `1px solid ${COLORS.border}` },
  summaryLabel: { margin: 0, fontSize: '0.85rem', color: COLORS.textMuted, marginBottom: '5px' },
  summaryValue: { margin: 0, fontSize: '1.4rem', fontWeight: 800 },
  loadingCard: { display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '100px' },
  spinner: { width: '40px', height: '40px', border: `4px solid ${COLORS.border}`, borderTop: `4px solid ${COLORS.primary}`, borderRadius: '50%', animation: 'spin 1s linear infinite', marginBottom: '20px' },
  errorCard: { padding: '40px', textAlign: 'center', backgroundColor: COLORS.dangerLight, borderRadius: '15px', border: `1px solid ${COLORS.danger}` },
  errorTitle: { color: COLORS.danger, fontWeight: 800 },
  retryBtn: { marginTop: '20px', padding: '10px 25px', backgroundColor: COLORS.danger, color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }
};

// Injection du CSS pour l'animation du spinner
const styleSheet = document.createElement("style");
styleSheet.innerText = `@keyframes spin { to { transform: rotate(360deg); } }`;
document.head.appendChild(styleSheet);

export default Dashboard;
